// One Apify run for the whole batch is cheaper and faster than one run per row.
// Rows that already have "enriched_at" are skipped, so re-running only enriches new rows.
const domains = [...new Set($input.all()
  .filter(i => i.json.domain && !i.json.enriched_at)
  .map(i => String(i.json.domain).trim()))].slice(0, 200);
if (!domains.length) return [];
return [{ json: { domains } }];
